36	export interface BbrTruthResult {
37	  id: string;
38	  /** True when a value exists for this id (verified or not). */
39	  supported: boolean;
40	  /** True only when the value is scrape-verified and may anchor a data-quality verdict. */
41	  verified: boolean;
42	  value: string | number | null;
43	  extra?: Record<string, unknown>;
44	  asOf: string;
45	  source?: string;
46	}
