48	const LEADER_BLOCKS = new Set([
49	  'career_points_leaders',
50	  'career_assists_leaders',
51	  'career_rebounds_leaders',
52	  'career_steals_leaders',
53	  'career_blocks_leaders',
54	  'career_three_pointers_leaders',
55	]);
56	
57	function seasonEndYear(season: string): number | null {
58	  const m = season.match(/^(\d{4})-(\d{2})$/);
59	  if (!m) return null;
60	  const startCentury = Math.floor(Number(m[1]) / 100) * 100;
61	  const end = startCentury + Number(m[2]);
62	  return end < Number(m[1]) ? end + 100 : end;
63	}
64	
65	const asOf = (): string => TRUTH._meta?.asOf ?? 'unknown';
66	
67	function none(id: string): BbrTruthResult {
68	  return { id, supported: false, verified: false, value: null, asOf: asOf() };
69	}
