86	        id,
87	        supported: false,
88	        verified: false,
89	        value: null,
90	        asOf: asOf(),
91	        source: block.source,
92	      };
93	    return {
94	      id,
95	      supported: true,
96	      verified: !!block.verified,
97	      value: row.player,
98	      extra: { value: row.value },
99	      asOf: asOf(),
100	      source: block.source,
101	    };
102	  }
103	
104	  // player_career_totals.<Player>.<stat>
105	  if (head === 'player_career_totals') {
106	    const player = p(1);
