154	    const block = t.team_records?.[key];
155	    if (!block || block.wins == null) return none(id);
156	    return {
157	      id,
158	      supported: true,
159	      verified: !!block.verified,
160	      value: `${block.wins}-${block.losses}`,
161	      extra: { wins: block.wins, losses: block.losses },
162	      asOf: asOf(),
163	      source: block.source,
164	    };
165	  }
166	
167	  // season_leaders_2024.<stat>.<rank> (rank 1 only)
168	  if (head === 'season_leaders_2024') {
169	    const block = t.season_leaders_2024?.[p(1)];
170	    if (!block?.leader) return none(id);
171	    return {
172	      id,
173	      supported: true,
174	      verified: !!block.verified,
175	      value: block.leader.player,
176	      extra: { value: block.leader.value },
177	      asOf: asOf(),
178	      source: block.source,
179	    };
180	  }
181	
182	  // single_games.2016_finals_game7[.leading_scorers]
183	  if (head === 'single_games') {
184	    const block = t.single_games?.[p(1)];
185	    if (!block) return none(id);
186	    if (p(2) === 'leading_scorers') {
187	      const top = [...block.leading_scorers].sort(
188	        (a: { points: number }, b: { points: number }) => b.points - a.points,
189	      )[0];
190	      if (!top) return none(id);
191	      return {
192	        id,
193	        supported: true,
194	        verified: !!block.verified,
195	        value: top.player,
196	        extra: { points: top.points },
197	        asOf: asOf(),
198	        source: block.source,
199	      };
200	    }
201	    return {
202	      id,
203	      supported: true,
204	      verified: !!block.verified,
205	      value: `${block.away_team} ${block.away_score}, ${block.home_team} ${block.home_score}`,
206	      extra: { away_score: block.away_score, home_score: block.home_score },
207	      asOf: asOf(),
208	      source: block.source,
209	    };
210	  }
211	
212	  return none(id);
213	}

